void _markSourceOpeningChronology(
  List<Map<String, dynamic>> openings,
  List<Map<String, dynamic>> history,
) {
  DateTime? timeOf(Map<String, dynamic> row) =>
      DateTime.tryParse(row['captured_at']?.toString() ?? '');
  for (final opening in openings) {
    final openingTime = timeOf(opening);
    opening['_opening_time_conflict'] =
        openingTime != null &&
        history.any((row) {
          final observed = timeOf(row);
          return observed != null && observed.isBefore(openingTime);
        });
  }
}

String _sourceOpeningLabel(Map<String, dynamic> row, String time) =>
    row['_opening_time_conflict'] == true
    ? 'KAYNAK AÇILIŞI\n$time\nTarih çelişkisi'
    : 'KAYNAK AÇILIŞI\n$time';

bool _hasPerformanceData(Map<String, dynamic> d) {
  final meta = d['meta'];
  final engineVersion = meta is Map
      ? int.tryParse(meta['engineVersion']?.toString() ?? '')
      : null;

  final normalizedCache =
      meta is Map &&
      meta['analysisNormalizationVersion'] == 'cached-unique-match-analysis-v1';
  return ((engineVersion != null &&
              engineVersion == performanceEngineVersion) ||
          normalizedCache) &&
      d['evTakimi'] is Map &&
      d['deplasmanTakimi'] is Map;
}

String _friendlyPerformanceError(Object e) {
  final raw = e.toString().replaceFirst('Exception: ', '');
  final low = raw.toLowerCase();

  if (low.contains('connection abort') ||
      low.contains('connection reset') ||
      low.contains('timed out') ||
      low.contains('timeout')) {
    return 'Bağlantı kesildi. Hazırlama sunucuda devam ediyor olabilir.';
  }

  return raw;
}

